static void check_cond(bool cond, const char* msg) {
    if (cond) {
        g_pass_cnt++;
    } else {
        g_fail_cnt++;
        std::printf("  [FAIL] %s\n", (msg != nullptr) ? msg : "unknown");
    }
}

/**
 * @brief 解析相对路径为可用文件绝对路径
 */
static bool resolve_path(const char* rel, char* out_buf, size_t cap) {
    if (rel == nullptr || out_buf == nullptr || cap == 0U) return false;
    const char* prefixes[] = {
        "", "../", "../../", "../../../", "/workspace/soc-ap/",
        "/home/sushaohua/workspace/ai_soc_project/soc-ap/"
    };
    for (size_t i = 0U; i < 6U; ++i) {
        char full[512] = {0};
        std::snprintf(full, sizeof(full), "%s%s", prefixes[i], rel);
        if (access(full, F_OK) == 0) {
            if (realpath(full, out_buf) != nullptr) return true;
            std::snprintf(out_buf, cap, "%s", full);
            return true;
        }
    }
    return false;
}

