    char bin[512] = {0};
    char lib[512] = {0};
    if (!resolve_path("config/dbus/twin/session_twin.conf", conf, sizeof(conf)) ||
        !resolve_path("third_party/install/bin/dbus-daemon", bin, sizeof(bin))) {
        return -1;
    }
    const bool ok_lib = resolve_path("third_party/install/lib", lib, sizeof(lib));
    int pfd[2];
    if (pipe(pfd) != 0) return -1;
    const pid_t pid = fork();
    if (pid == 0) {
        if (ok_lib) setenv("LD_LIBRARY_PATH", lib, 1);
        close(pfd[0]);
        dup2(pfd[1], STDOUT_FILENO);
        close(pfd[1]);
        execl(bin, bin, "--config-file", conf, "--print-address", "--nofork", (char*)nullptr);
        _exit(127);
    }
    close(pfd[1]);
    char buf[256] = {0};
    const ssize_t n = read(pfd[0], buf, sizeof(buf) - 1U);
    close(pfd[0]);
    if (n <= 0) {
        kill(pid, SIGTERM);
        return -1;
    }
    char* nl = std::strchr(buf, '\n');
    if (nl != nullptr) *nl = '\0';
    std::snprintf(out_addr, addr_len, "%s", buf);
    return pid;
}

