    def test_04_i18n_dictionary_parity(self):
        """校验 zh-CN 与 en-US 双语字典键名 100% 对齐。"""
        # Extract I18N object from app.js using regex
        match = re.search(r"var I18N = (\{[\s\S]*?\n    \});", self.js_content)
        self.assertIsNotNone(match, "I18N dictionary must be present in app.js")
        raw_dict = match.group(1)

        # Parse zh-CN and en-US keys
        zh_match = re.search(r"'zh-CN': \{([\s\S]*?)\n        \},", raw_dict)
        en_match = re.search(r"'en-US': \{([\s\S]*?)\n        \}", raw_dict)
        self.assertIsNotNone(zh_match)
        self.assertIsNotNone(en_match)

        zh_keys = set(re.findall(r"^\s+([a-zA-Z0-9_]+)\s*:", zh_match.group(1), re.MULTILINE))
        en_keys = set(re.findall(r"^\s+([a-zA-Z0-9_]+)\s*:", en_match.group(1), re.MULTILINE))

        self.assertTrue(len(zh_keys) > 30, f"zh-CN dictionary too small ({len(zh_keys)})")
        self.assertEqual(zh_keys, en_keys, f"Dictionary key mismatch: {zh_keys ^ en_keys}")

