/**
 * @brief 校验料槽配置 JSON 中的 mixing_weight 单槽范围 [0, 10000] 及总和严格等于 10000
 * @param body 请求 JSON 字符串
 * @param err_msg 错误原因输出缓冲区
 * @param err_cap 错误缓冲区容量
 * @return bool 校验通过返回 true，否则返回 false
 */
static bool validate_mixing_weights_in_body(const char* body, char* err_msg, size_t err_cap) {
    if (body == nullptr) return true;
    const char* cursor = body;
    long weight_sum = 0L;
    size_t weight_count = 0U;
    while ((cursor = std::strstr(cursor, "\"mixing_weight\":")) != nullptr) {
        cursor += 16;
        while (*cursor == ' ' || *cursor == '\t') cursor++;
        char* endptr = nullptr;
        const long w = std::strtol(cursor, &endptr, 10);
        if (endptr == cursor || w < 0L || w > 10000L) {
            std::snprintf(err_msg, err_cap, "Invalid mixing_weight: must be in [0, 10000]");
            return false;
        }
        weight_sum += w;
        weight_count++;
        cursor = endptr;
    }
    if (weight_count > 0U && weight_sum != 10000L) {
        std::snprintf(err_msg, err_cap, "Invalid mixing_weight sum: %ld != 10000", weight_sum);
        return false;
    }
    return true;
}

/**
 * @brief 解析并强校验 POST /api/v1/filament/slots 请求体（ISS-007 & ISS-010）
 * @param body 请求 JSON 字符串
 * @param out_params 输出解析后的耗材控制参数结构体指针
 * @param err_msg 错误原因输出缓冲区
 * @param err_cap 错误缓冲区容量
 * @return bool 合法返回 true，越界或非法返回 false
 */
static bool validate_filament_slots_body(
    const char* body,
    ui_gw_filament_params_t* out_params,
    char* err_msg,
    size_t err_cap
) {
    if (out_params == nullptr) return false;
    *out_params = { 1U, 0U, 0 };
    if (body == nullptr || body[0] == '\0') return true;
    if (!validate_mixing_weights_in_body(body, err_msg, err_cap)) return false;

    const char* ps = std::strstr(body, "\"active_slot\":");
    const size_t key_len = (ps != nullptr) ? 14U : 10U;
    if (ps == nullptr) ps = std::strstr(body, "\"slot_id\":");
    if (ps != nullptr) {
        const long slot_val = std::strtol(ps + key_len, nullptr, 10);
        if (slot_val < 1L || slot_val > 4L) {
            std::snprintf(err_msg, err_cap, "Invalid slot_id: %ld (must be 1..4)", slot_val);
            return false;
        }
        out_params->slot_id = (uint8_t)slot_val;
    }
    const char* pa = std::strstr(body, "\"action\":");
    if (pa != nullptr) {
        const char* val_p = pa + 9;
        while (*val_p == ' ' || *val_p == '\t') val_p++;
        if (*val_p == '\"') {
            if (std::strncmp(val_p, "\"select\"", 8) == 0) out_params->action = 0U;
            else if (std::strncmp(val_p, "\"load\"", 6) == 0) out_params->action = 1U;
            else if (std::strncmp(val_p, "\"unload\"", 8) == 0) out_params->action = 2U;
            else {
                std::snprintf(err_msg, err_cap, "Invalid filament action string");
                return false;
            }
        } else {
            char* endptr = nullptr;
            const long act_val = std::strtol(val_p, &endptr, 10);
            if (endptr == val_p || act_val < 0L || act_val > 2L) {
                std::snprintf(err_msg, err_cap, "Invalid filament action code: %ld (must be 0..2)", act_val);
                return false;
            }
            out_params->action = (uint8_t)act_val;
        }
    }
    const char* pt = std::strstr(body, "\"target_temp_deci_c\":");
    if (pt != nullptr) {
        out_params->target_temp_deci_c = (int32_t)std::strtol(pt + 21, nullptr, 10);
    }
    return true;
}

/**
 * @brief 处理 POST /api/v1/filament/slots 请求（真实 D-Bus 与串口 0x19 闭环，默认 SELECT 不触发 210°C）
 * @param server 服务端实例指针
 * @param client 客户端连接槽指针
 * @param body 请求 JSON 字符串
 */
static void handle_filament_slots_route(ui_gw_server_t* server, client_conn_t* client, const char* body) {
    if (server == nullptr || client == nullptr) return;
    ui_gw_filament_params_t params = { 1U, 0U, 0 };
    char err_msg[128] = {0};
    if (!validate_filament_slots_body(body, &params, err_msg, sizeof(err_msg))) {
        send_400_bad_request(client, err_msg);
        return;
    }
    if (!server->is_hw_online) {
        send_503_offline(client, "Hardware offline: cannot control filament");
        return;
    }
    ui_gw_filament_result_t res = { 0U, 0U };
    const ui_gw_status_t st = ui_gw_dbus_control_filament(server->dbus_client, &params, &res);
    if (st != UI_GW_OK) {
        send_504_timeout(client, "Filament control RPC timeout or NACK");
        return;
    }
    char json_ok[256] = {0};
    std::snprintf(json_ok, sizeof(json_ok),
                  "{\"status\":\"ok\",\"code\":0,\"active_slot\":%u,\"filament_state\":%u,"
                  "\"action\":%u,\"target_temp_deci_c\":%d,\"message\":\"Filament slots updated\"}",
                  (unsigned)res.active_slot, (unsigned)res.filament_state,
                  (unsigned)params.action, (int)params.target_temp_deci_c);
    send_json_and_close(client, 200, json_ok);
}

