    if (body == nullptr || out_name == nullptr || cap == 0U) return false;
    const char* keys[] = { "\"name\":\"", "\"filename\":\"", "\"model\":\"" };
    for (size_t i = 0U; i < 3U; ++i) {
        const char* p = std::strstr(body, keys[i]);
        if (p != nullptr) {
            const char* start = p + std::strlen(keys[i]);
            const char* end = std::strchr(start, '\"');
            if (end != nullptr && end > start && (size_t)(end - start) < cap) {
                std::memcpy(out_name, start, (size_t)(end - start));
                out_name[end - start] = '\0';
                return true;
            }
        }
    }
    return false;
}

/**
 * @brief 处理 POST /api/v1/jobs/upload 路由：校验扩展名、大小及 G/M/T 指令合法性（ISS-008 & ISS-009）
 * @param client 客户端连接槽指针
 * @param body 请求 JSON 字符串
 */
static void handle_job_upload_route(client_conn_t* client, const char* body) {
    if (client == nullptr) return;
    if (body == nullptr || body[0] == '\0') {
        send_400_bad_request(client, "Empty upload body");
        return;
    }
    char filename[128] = {0};
    if (!extract_upload_filename(body, filename, sizeof(filename)) || !has_valid_gcode_extension(filename)) {
        send_400_bad_request(client, "Invalid G-code file extension: only .gcode/.gco/.nc allowed");
        return;
    }
    const bool is_preset = (std::strstr(body, "\"preset\":true") != nullptr) ||
                           (std::strstr(body, "\"preset\": true") != nullptr);
    if (!is_preset) {
        const char* ps = std::strstr(body, "\"size\":");
        if (ps != nullptr && std::strtol(ps + 7, nullptr, 10) <= 0L) {
            send_400_bad_request(client, "Invalid G-code file size: empty file rejected");
            return;
        }
        const char* pc = std::strstr(body, "\"content\":\"");
        const char* check_src = (pc != nullptr) ? (pc + 11) : body;
        if (!contains_valid_gcode_command(check_src)) {
            send_400_bad_request(client, "Invalid G-code content: no valid G/M/T commands found");
            return;
        }
    }
    char json_ok[256] = {0};
    std::snprintf(json_ok, sizeof(json_ok),
                  "{\"status\":\"ok\",\"code\":0,\"model\":\"%s\",\"message\":\"Upload staged\"}", filename);
    send_json_and_close(client, 200, json_ok);
}

/**
 * @brief 处理 POST /api/v1/jobs/start 启动打印作业路由
 * @param server 服务端实例指针
 * @param client 客户端连接槽指针
 * @param body 请求 JSON 字符串
 */
static void handle_job_start_route(ui_gw_server_t* server, client_conn_t* client, const char* body) {
    if (server == nullptr || client == nullptr) return;
    if (!server->is_hw_online) {
        send_503_offline(client, "Hardware offline: cannot start job");

    char chunk[4096];
    size_t n = 0;
    while ((n = std::fread(chunk, 1, sizeof(chunk), fp)) > 0) {
        (void)send(fd, chunk, n, MSG_NOSIGNAL);
    }
}

/**
 * @brief 处理静态文件请求或未知路径 HTTP 404 响应（ISS-017 扩容缓冲区防截断）
 * @param server 服务端实例指针
 * @param client 客户端连接槽指针
 * @param rel_path 请求相对路径
 */
static void handle_static_route(ui_gw_server_t* server, client_conn_t* client, const char* rel_path) {
    if (server == nullptr || client == nullptr || rel_path == nullptr) return;
    const char* path_clean = (std::strcmp(rel_path, "/") == 0) ? "index.html" :
                             (rel_path[0] == '/') ? &rel_path[1] : rel_path;
    char full_path[512];
    const char* root = (server->static_root[0] != '\0') ? server->static_root : ".";
    std::snprintf(full_path, sizeof(full_path), "%s/%s", root, path_clean);

    FILE* fp = std::fopen(full_path, "rb");
    if (fp == nullptr) {
        char err_resp[512] = {0};
        ui_gw_http_build_error_response(404, "Not Found", err_resp, sizeof(err_resp));
        send_http_response(client->client_fd, err_resp);
        close_client(client);
        return;
    }
    std::fseek(fp, 0, SEEK_END);
    const long sz = std::ftell(fp);
    std::fseek(fp, 0, SEEK_SET);

    const char* mime = get_mime_type(full_path);
    std::printf("[UI_GW DEBUG] HTTP 200 Static: '%s' (%ld bytes, %s)\n", full_path, sz, mime);
    std::fflush(stdout);
    send_file_content(fp, sz, mime, client->client_fd);
    std::fclose(fp);
    close_client(client);
}
